import hashlib
import json
import logging
from abc import abstractmethod, ABC
from collections import defaultdict
from typing import Dict, List, Any, Optional, Union
import re

from langchain_core.documents import Document
from langchain_core.embeddings import Embeddings
from langchain_core.vectorstores import VectorStore
from langchain_milvus import Milvus, BM25BuiltInFunction
from pymilvus import MilvusClient
from pymilvus.client.types import DataType
from unidecode import unidecode

from dataiku.core.vector_stores.dku_vector_store import DkuVectorStore
from dataiku.core.vector_stores.vector_store_document_filter import VectorStoreDocumentFilter, ColumnType
from dataiku.langchain import DKUEmbeddings
from dataiku.langchain.metadata_generator import DKU_SECURITY_TOKENS_META
from dataiku.llm.types import BaseVectorStoreQuerySettings

BM25_INDEX_NAME = "sparse"

class MilvusBaseVectorStore(DkuVectorStore, ABC):
    DEFAULT_REQUIRED_FIELD_NAMES = {
        "id": "pk",
        "content": "text",
        "vector": "vector",
    }

    def __init__(self, *args, **kwargs):
        self._conn_args = {}
        self.collection_name = None
        super().__init__(*args, **kwargs)
        self.original_to_sanitized_column_name = None
        self._sanitize_meta_columns_names()
        self.milvus_metadata_schema = self._build_metadata_schema()

    def _sanitize_meta_columns_names(self):
        col_names = list(self.metadata_column_type_and_meaning.keys())
        self.original_to_sanitized_column_name = self.get_column_name_map(col_names, self.source_id_column)
        # Map attributes to their clean names
        self.metadata_column_type_and_meaning = {
            self.original_to_sanitized_column_name[k]: v for k, v in self.metadata_column_type_and_meaning.items()
        }
        self.source_id_column = self.original_to_sanitized_column_name.get(self.source_id_column)

    @staticmethod
    def get_column_name_map(column_names, source_id_col) -> Optional[Dict[str, str]]:
        if source_id_col:
            column_names.append(source_id_col)
        return MilvusBaseVectorStore.map_metadata_to_sanitized(column_names)

    @staticmethod
    def map_metadata_to_sanitized(column_names: List[str]):
        # Check for conflicts. Columns could map to the same string
        conflict_map = defaultdict(list)
        for original in column_names:
            clean_name = MilvusBaseVectorStore._sanitize_name(original)
            conflict_map[clean_name].append(original)

        original_to_clean_names = {}
        for clean, originals in conflict_map.items():
            if len(originals) > 1:
                # We have conflicts, suffix all clean names by md5 hash of original
                for original in originals:
                    md5_hash = hashlib.md5(original.encode()).hexdigest()
                    original_to_clean_names[original] = clean + "_" + md5_hash
            else:
                original_to_clean_names[originals[0]] = clean

        return original_to_clean_names


    @staticmethod
    def _sanitize_name(column_name):
        output = unidecode(column_name)
        output = re.sub("[^A-Za-z0-9_]", "_", output)
        if re.match("^[0-9]", output):
            output = "_" + output
        return output

    @staticmethod
    def _get_search_kwargs(query_settings: BaseVectorStoreQuerySettings) -> Dict:
        kwargs = DkuVectorStore._get_search_kwargs(query_settings)
        # Make sure we retrieve enough documents for hybrid search.
        # See https://github.com/langchain-ai/langchain-milvus/blob/libs/milvus/v0.2.1/libs/milvus/langchain_milvus/vectorstores/milvus.py#L1518
        # Performance is better with double fetch_k
        kwargs["fetch_k"] = 2 * kwargs["k"]
        return kwargs

    def _get_db_kwargs(self, query_settings: BaseVectorStoreQuerySettings) -> Dict:
        return {"hybrid": query_settings.get("searchType") == "HYBRID"}

    @staticmethod
    def _get_search_type(query_settings: BaseVectorStoreQuerySettings) -> str:
        search_type = query_settings.get("searchType")
        if search_type == "HYBRID":
            # The search type when calling `as_retriever` must be similarity.
            # Hybrid search is determined by our `hybrid` kwarg in `get_db`
            search_type = "SIMILARITY"
        return DkuVectorStore.dss_search_type_to_langchain_search_type(search_type)

    @staticmethod
    def _get_retriever_kwargs(query_settings: BaseVectorStoreQuerySettings) -> Dict:
        advanced_reranking = query_settings.get("useAdvancedReranking", False)
        if advanced_reranking:
            # Use recommended value for `k` (smoothing parameter)
            # See https://milvus.io/docs/rrf-ranker.md#RRF-Ranker:~:text=While,a%20common%20choice
            k = 60
            return {
                "ranker_type": "rrf",
                "ranker_params": {"k": k}
            }

        return {}

    @staticmethod
    def get_retriever_invoke_kwargs(query_settings: BaseVectorStoreQuerySettings) -> Dict:
        return MilvusBaseVectorStore._get_retriever_kwargs(query_settings)

    @staticmethod
    def _fix_metadata_in_results(results: List[tuple[Document, float]], mapping) -> List[tuple[Document, float]]:
        for doc, _ in results:
            for key, val in doc.metadata.items():
                # Milvus returns google.protobuf.pyext._message.RepeatedScalarContainer for array columns
                # We need to convert them to list to be json serializable
                if type(val).__name__ == "RepeatedScalarContainer":
                    doc.metadata[key] = list(val)
        return results

    def search_with_scores(self, query: str, embeddings: DKUEmbeddings, query_settings: BaseVectorStoreQuerySettings,
                           additional_search_kwargs: Optional[Dict] = None) -> List[tuple[Document, float]]:
        search_kwargs = self._get_search_kwargs(query_settings)
        if isinstance(additional_search_kwargs, dict):
            search_kwargs = {**search_kwargs, **additional_search_kwargs}

        db_kwargs = self._get_db_kwargs(query_settings)
        retriever_kwargs = self._get_retriever_kwargs(query_settings)
        vectorstore_db = self.get_db(embeddings, **db_kwargs)

        if query_settings.get("searchType") == "HYBRID":
            # We avoid calling `similarity_search_with_relevance_scores` because no relevance function exists in hybrid mode.
            # The WeightedRanker of Milvus normalizes and combines the scores between the two types of search.
            results = vectorstore_db.similarity_search_with_score(query, **search_kwargs, **retriever_kwargs)
        else:
            results = vectorstore_db.similarity_search_with_relevance_scores(query, **search_kwargs, **retriever_kwargs)

        return self._fix_metadata_in_results(results, self._get_required_field_names())

    @staticmethod
    def _patch_output_fields(milvus_vs: VectorStore):
        def _remove_forbidden_fields(fields: List[str]) -> List[str]:
            # The raw data of BM25 index is not allowed to be retrieved.
            # We remove it from the fields we expect the KB to return.
            return [field for field in fields if field != BM25_INDEX_NAME]

        milvus_vs._remove_forbidden_fields = _remove_forbidden_fields

    def get_db(self, embeddings: Embeddings, allow_creation: bool = False, **kwargs: Any) -> VectorStore:
        if self._db_exists():
            hybrid = kwargs.get("hybrid", False)
        elif allow_creation:
            # At creation time, the hybrid index is required so that we create the correct schema
            hybrid = True
        else:
            # DB doesn't exist and allow_creation is False
            raise Exception("Milvus vector store doesn't exist yet, you may need to run the embedding recipe.")

        field_names = self._get_required_field_names()
        builtin_function = None
        vector_field = [field_names["vector"]]
        index_params = [{"index_type": "FLAT", "metric_type": self.get_distance_metric()}]
        if hybrid:
            builtin_function = BM25BuiltInFunction()
            vector_field.append(BM25_INDEX_NAME)
            index_params.append({"index_type": "SPARSE_INVERTED_INDEX", "metric_type": "BM25"})

        db = Milvus(
            embedding_function=embeddings,
            builtin_function=builtin_function,
            connection_args=self._conn_args,
            collection_name=self.collection_name,
            primary_field=field_names["id"],
            text_field=field_names["content"],
            vector_field=vector_field,
            index_params=index_params,
            metadata_schema=self.milvus_metadata_schema,
        )
        self._patch_output_fields(db)
        return db

    def include_similarity_score(self, query_settings: BaseVectorStoreQuerySettings) -> bool:
        # We always want KB search tool to go through `search_with_scores`,
        #  so that `_fix_metadata_in_results` is called.
        return True

    def get_document_metadata(self, document: Document, column: str) -> Optional[Any]:
        clean_col = self.original_to_sanitized_column_name.get(column, column)
        column_type, meaning = self.metadata_column_type_and_meaning.get(clean_col, (None, None))
        if meaning == "BagOfWordsMeaning":
            return list(document.metadata.get(clean_col, []))
        else:
            return document.metadata.get(clean_col, None)


    @abstractmethod
    def get_distance_metric(self):
        pass

    @abstractmethod
    def _db_exists(self):
        pass

    @abstractmethod
    def _build_metadata_schema(self):
        pass

class MilvusBaseDocumentFilter(VectorStoreDocumentFilter, ABC):
    """ Milvus uses Python-like operators
    See https://milvus.io/docs/basic-operators.md
    And further examples for each data type, e.g. https://milvus.io/docs/string.md
    """

    def __init__(self, metadata_column_type_and_meaning: Dict, original_to_clean_column_map: Dict):
        super().__init__(metadata_column_type_and_meaning)
        self.original_to_clean_column_map = original_to_clean_column_map

    @abstractmethod
    def _convert_item(self, item, column_type):
        pass

    def _coerce_value(self, clause: Dict) -> Union[List, str, int, float]:
        value = clause["value"]
        column_type = self._get_column_type(clause)
        if type(value) == list:
            return [self._convert_item(item, column_type) for item in value]
        elif type(value) == str:
            return '"' + value + '"'
        else:
            return self._convert_item(value, column_type)

    def _get_clean_col(self, clause):
        original = clause["column"]
        # Default to original if there is no mapping
        return self.original_to_clean_column_map.get(original, original)

    def convert(self, clause: Dict) -> str:
        if clause["operator"] == "EQUALS":
            column_type = self._get_column_type(clause)
            if column_type == ColumnType.BagOfWords:
                return f'ARRAY_CONTAINS({self._get_clean_col(clause)}, {self._coerce_value(clause)})'
            return f'({self._get_clean_col(clause)} == {self._coerce_value(clause)})'
        elif clause["operator"] == "NOT_EQUALS":
            column_type = self._get_column_type(clause)
            if column_type == ColumnType.BagOfWords:
                raise Exception("Milvus local vector store doesn't support `not` clause on 'bag-of-words' columns.")
            return f'({self._get_clean_col(clause)} != {self._coerce_value(clause)})'
        elif clause["operator"] == "GREATER_THAN":
            return f'({self._get_clean_col(clause)} > {self._coerce_value(clause)})'
        elif clause["operator"] == "LESS_THAN":
            return f'({self._get_clean_col(clause)} < {self._coerce_value(clause)})'
        elif clause["operator"] == "GREATER_OR_EQUAL":
            return f'({self._get_clean_col(clause)} >= {self._coerce_value(clause)})'
        elif clause["operator"] == "LESS_OR_EQUAL":
            return f'({self._get_clean_col(clause)} <= {self._coerce_value(clause)})'
        elif clause["operator"] == "IN_ANY_OF":
            column_type = self._get_column_type(clause)
            if column_type == ColumnType.BagOfWords:
                clauses = [{"column": self._get_clean_col(clause), "operator": "EQUALS", "value": v} for v in clause["value"]]
                return self.convert({"operator": "OR", "clauses": clauses})
            return f'({self._get_clean_col(clause)} in {self._coerce_value(clause)})'
        elif clause["operator"] == "IN_NONE_OF":
            column_type = self._get_column_type(clause)
            if column_type == ColumnType.BagOfWords:
                raise Exception("Milvus local vector store doesn't support `not` clause on 'bag-of-words' columns.")
            return f'({self._get_clean_col(clause)} not in {self._coerce_value(clause)})'
        elif clause["operator"] == "CONTAINS":
            return f'({self._get_clean_col(clause)} LIKE %{self._coerce_value(clause)}%)'
        elif clause["operator"] == "AND":
            return '(' + ' and '.join([self.convert(x) for x in clause["clauses"]]) + ')'
        elif clause["operator"] == "OR":
            return '(' + ' or '.join([self.convert(x) for x in clause["clauses"]]) + ')'
        # custom operator to search a string in a list of strings, used for security tokens, not exposed to users
        elif clause["operator"] == "ARRAY_CONTAINS":
            return f'ARRAY_CONTAINS({self._get_clean_col(clause)}, {self._coerce_value(clause)})'
        else:
            raise ValueError("Unsupported filter operator for Milvus local vector store: %s" % clause["operator"])

    def _and_filter(self, converted_clause_a: str, converted_clause_b: str) -> str:
        return f'({converted_clause_a} and {converted_clause_b})'

    def _get_filter_field_name(self) -> str:
        return "expr"

    def add_security_tokens_to_document(self, document: Document) -> Document:
        """ Add a field with the list of security tokens useful to implement add_security_filter()
        """
        if DKU_SECURITY_TOKENS_META in document.metadata:
            document.metadata[DKU_SECURITY_TOKENS_META] = json.loads(document.metadata[DKU_SECURITY_TOKENS_META])
            logging.info("Updated metadata to %s" % self._sanitize_metadata_for_print(document.metadata))

        return document

    def _get_security_token_check_clause(self, security_token: str) -> Dict:
        return {
            "operator": "ARRAY_CONTAINS",
            "column": DKU_SECURITY_TOKENS_META,
            "value": security_token,
        }

    def _get_column_type(self, clause: Dict) -> Optional[ColumnType]:
        clean_column = self._get_clean_col(clause)
        dss_storage_type, meaning  = self.metadata_column_type_and_meaning.get(clean_column, (None, None))
        return ColumnType.from_dss_type(dss_storage_type, meaning)
